from collections import deque
adj = {0: [1, 2], 1: [0, 3, 4], 2: [0, 4], 3: [1], 4: [1, 2]}
dist = {0: 0}
parent = {0: None}
order = []
queue = deque([0])
while queue:
    u = queue.popleft()
    order.append(u)
    for v in adj[u]:
        if v not in dist:
            dist[v] = dist[u] + 1
            parent[v] = u
            queue.append(v)
assert order == [0, 1, 2, 3, 4]
assert [dist[i] for i in range(5)] == [0, 1, 1, 2, 2]
assert sum(dist.values()) == 6 and parent[4] == 1
color = {v: "w" for v in adj}
discovery = []
tree = []
back = []

def visit(u, p):
    color[u] = "g"
    discovery.append(u)
    for v in adj[u]:
        if color[v] == "w":
            tree.append((u, v))
            visit(v, u)
        elif color[v] == "g" and v != p:
            back.append((u, v))
    color[u] = "b"

visit(0, None)
assert discovery == [0, 1, 3, 4, 2] and back == [(2, 0)] and len(tree) == 4
assert min(5, 1 + 1) == 2
print(order, discovery, sum(dist.values()))
